<style>
@font-face{font-family:"BOOK920 Sans";src:url("/theme-demo/book920/fonts/BeVietnamPro-Regular.ttf") format("truetype");font-weight:400;font-display:swap}
@font-face{font-family:"BOOK920 Sans";src:url("/theme-demo/book920/fonts/BeVietnamPro-SemiBold.ttf") format("truetype");font-weight:600;font-display:swap}
@font-face{font-family:"BOOK920 Sans";src:url("/theme-demo/book920/fonts/BeVietnamPro-Bold.ttf") format("truetype");font-weight:700;font-display:swap}
:root{--book20-navy:#04344f;--book20-teal:#08728c;--book20-soft:#d8e9ef;--book20-orange:#ff6b18;--book20-ink:#062f49}
*{box-sizing:border-box}body{margin:0;font-family:"BOOK920 Sans",Arial,sans-serif;color:var(--book20-ink);background:#fff}.book20-page a{text-decoration:none;color:inherit}.book20-container{width:min(1600px,calc(100% - 48px));margin:auto}.book20-topbar{background:var(--book20-teal);color:#fff}.book20-topbar .book20-container{height:58px;display:flex;align-items:center;gap:36px}.book20-topbar form{margin-left:auto;background:#fff;border-radius:28px;display:flex;width:330px}.book20-topbar input{border:0;background:none;padding:12px 18px;flex:1;outline:0}.book20-topbar button{border:0;background:none;padding:0 16px;font-size:20px}.book20-header-main{height:108px;display:flex;align-items:center;gap:42px}.book20-logo{width:290px;align-self:stretch;display:grid;place-items:center;background:var(--book20-navy);color:#fff!important;font-size:36px;font-weight:800}.book20-logo img{max-width:210px;max-height:70px}.book20-logo i{color:var(--book20-orange)}.book20-header nav{display:flex;gap:34px;align-items:center;justify-content:center;flex:1;font-weight:700}.book20-header nav a:first-child{color:var(--book20-orange)}.book20-actions{display:flex;gap:12px}.book20-actions>*{width:48px;height:48px;border:1px solid #dde5e8;background:#fff;border-radius:50%;display:grid;place-items:center;position:relative}.book20-actions em{position:absolute;right:-4px;top:-7px;background:var(--book20-teal);color:#fff;border-radius:50%;font-style:normal;padding:3px 7px}.book20-menu-toggle{display:none}.book20-hero{height:min(670px,68vw);position:relative;overflow:hidden}.book20-hero article{position:absolute;inset:0;opacity:0;transition:.6s}.book20-hero article.is-active{opacity:1}.book20-hero img{width:100%;height:100%;object-fit:cover}.book20-hero article>div{position:absolute;left:10%;top:42%;color:white;text-shadow:0 2px 12px #000;max-width:570px}.book20-dots{position:absolute;bottom:22px;left:50%;display:flex;gap:9px}.book20-dots button{width:12px;height:12px;border:0;border-radius:50%;background:#ffffff88}.book20-dots .is-active{background:#fff}.book20-section{padding:76px 0}.book20-benefits{padding:44px 0}.book20-benefit-grid{background:var(--book20-soft);border-radius:14px;display:grid;grid-template-columns:repeat(4,1fr);padding:24px;gap:22px}.book20-benefit-grid article{display:flex;gap:18px;align-items:center}.book20-benefit-grid i{width:72px;height:72px;border-radius:8px;background:var(--book20-teal);color:#fff;display:grid;place-items:center;font-size:30px}.book20-benefit-grid h3,.book20-benefit-grid p{margin:0 0 6px}.book20-section-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:38px}.book20-section-head h2{font-size:40px;margin:0}.book20-section-head>a{border:1px solid #dce3e6;padding:15px 28px;border-radius:28px;font-weight:700}.book20-section-head.center{justify-content:center;text-align:center}.book20-product-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:28px}.book20-product{min-width:0}.book20-product-image{height:350px;border:1px solid #e1e6e8;border-radius:12px;display:grid;place-items:center;position:relative;background:#fff;overflow:hidden}.book20-product-image img{width:100%;height:100%;object-fit:contain}.book20-new{position:absolute;left:14px;top:0;background:#e4ecef;color:#222;padding:9px 7px;writing-mode:vertical-rl}.book20-product h3{min-height:50px;font-size:18px;line-height:1.45}.book20-product p{display:flex;gap:12px;align-items:center}.book20-product strong{color:var(--book20-orange);font-size:20px}.book20-product del{color:#999}.book20-product em{margin-left:auto;background:var(--book20-teal);color:#fff;border-radius:5px;padding:6px;font-style:normal}.book20-cart{display:block;text-align:center;background:var(--book20-soft);color:var(--book20-teal)!important;padding:14px;border-radius:28px;font-weight:700}.book20-products:nth-of-type(4){background:#f8fbfc}.book20-promo{padding-top:30px}.book20-promo>.book20-container{min-height:380px;background:var(--book20-soft);border-radius:30px;display:grid;grid-template-columns:1fr 1fr;align-items:center;padding:52px 7%;overflow:hidden}.book20-promo h2{font-size:38px;max-width:590px}.book20-promo small{color:var(--book20-orange);font-weight:800}.book20-promo a{display:inline-block;background:var(--book20-teal);color:#fff!important;padding:16px 32px;border-radius:28px;font-weight:700}.book20-promo-books{display:flex;align-items:center;justify-content:center;gap:18px;transform:rotate(-7deg)}.book20-promo-books img{width:28%;aspect-ratio:3/4;object-fit:cover;box-shadow:0 15px 30px #063e5a30}.book20-hot{background:var(--book20-soft)}.book20-hot>.book20-container{background:#fff;border-radius:28px;padding:45px}.book20-hot-grid{display:grid;grid-template-columns:1fr 1fr;gap:26px}.book20-hot .book20-product{border:1px solid #e4e8ea;border-radius:15px;padding:20px;display:grid;grid-template-columns:220px 1fr;column-gap:24px}.book20-hot .book20-product-image{grid-row:1/5;height:270px}.book20-testimonial-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.book20-testimonial-grid article{border:1px solid #e3e7e9;border-radius:12px;padding:34px;box-shadow:0 7px 22px #063e5a12;font-size:18px;line-height:1.55}.book20-testimonial-grid article>div{display:flex;align-items:center;gap:16px}.book20-testimonial-grid span{width:70px;height:70px;border-radius:50%;display:grid;place-items:center;background:var(--book20-soft);font-size:28px}.book20-testimonial-grid strong small{display:block;font-weight:400;margin-top:5px}.book20-post-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:26px}.book20-post-grid article{border:1px solid #e2e8ea;border-radius:14px;padding:22px;box-shadow:0 6px 20px #063e5a10}.book20-post-grid img{width:100%;height:230px;object-fit:cover;border-radius:12px}.book20-post-grid small{display:block;margin:18px 0;color:#666}.book20-post-grid h3{font-size:20px}.book20-post-grid>a{font-weight:700}.book20-footer{background:var(--book20-navy);color:white;padding:56px 0}.book20-contact-strip{display:grid;grid-template-columns:repeat(3,1fr);gap:36px;padding-bottom:42px;border-bottom:1px solid #ffffff33}.book20-contact-strip>div{display:flex;gap:20px;align-items:center}.book20-contact-strip i{width:68px;height:68px;border:1px dashed #fff;border-radius:50%;display:grid;place-items:center;font-size:25px}.book20-contact-strip span{display:flex;flex-direction:column;gap:8px}.book20-footer-grid{display:grid;grid-template-columns:1.3fr 1fr 1fr 1.1fr;gap:55px;padding-top:50px}.book20-footer-grid section{display:flex;flex-direction:column;gap:14px}.book20-footer-grid h2,.book20-footer-grid h3{margin:0 0 18px}.book20-footer-grid p{line-height:1.6}.book20-social{display:flex;gap:12px}.book20-social a{width:42px;height:42px;border:1px solid #fff;border-radius:50%;display:grid;place-items:center}.book20-footer form{display:flex}.book20-footer input{padding:14px;border:0;min-width:0}.book20-footer button{background:var(--book20-teal);color:#fff;border:0;width:50px}[data-book20-reveal]{opacity:0;transform:translateY(34px);transition:opacity .7s ease,transform .7s ease}[data-book20-reveal].is-visible{opacity:1;transform:none}
@media(max-width:900px){.book20-container{width:min(100% - 28px,1600px)}.book20-topbar .book20-container{height:auto;padding:10px 0;gap:12px;font-size:12px;flex-wrap:wrap}.book20-topbar form{order:3;width:100%}.book20-header-main{height:78px}.book20-logo{width:auto;background:none;color:var(--book20-navy)!important;font-size:25px}.book20-menu-toggle{display:block;margin-left:auto;border:0;background:none;font-size:24px}.book20-header nav{display:none;position:absolute;z-index:30;top:136px;left:0;right:0;background:white;flex-direction:column;align-items:flex-start;padding:24px}.book20-header nav.is-open{display:flex}.book20-actions{display:none}.book20-hero{height:420px}.book20-benefit-grid,.book20-product-grid,.book20-hot-grid,.book20-testimonial-grid,.book20-post-grid,.book20-contact-strip,.book20-footer-grid{grid-template-columns:1fr}.book20-section{padding:45px 0}.book20-section-head h2{font-size:30px}.book20-section-head>a{padding:10px 14px}.book20-product-grid{grid-template-columns:repeat(2,1fr);gap:16px}.book20-product-image{height:245px}.book20-hot>.book20-container{padding:20px}.book20-hot .book20-product{display:block}.book20-promo>.book20-container{grid-template-columns:1fr;padding:35px}.book20-promo h2{font-size:28px}.book20-promo-books{margin-top:30px}.book20-post-grid{grid-template-columns:1fr 1fr}.book20-contact-strip{gap:20px}.book20-footer-grid{gap:30px}}@media(max-width:540px){.book20-product-grid,.book20-post-grid{grid-template-columns:1fr}.book20-topbar span:nth-child(2){display:none}.book20-product-image{height:330px}}
@media(prefers-reduced-motion:reduce){[data-book20-reveal]{opacity:1;transform:none;transition:none}}
.book20-footer-logo{display:block;max-width:190px;max-height:64px;object-fit:contain}
.book20-footer-grid>*,.book20-contact-strip>*{min-width:0}.book20-contact-strip strong{overflow-wrap:anywhere}.book20-footer form{max-width:100%}
</style>
